    export const getChatSendAttachmentUrl = (centerId: string,
    conversationId: string,
    params?: ChatSendAttachmentParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/v1/centers/${centerId}/conversations/${conversationId}/attachments?${stringifiedParams}` : `/v1/centers/${centerId}/conversations/${conversationId}/attachments`
}

